function getOutfitById(id) {
  return OUTFITS.find((o) => o.id === id || o.slug === id);
}

function outfitsForCategory(cat) {
  return OUTFITS.filter((o) =>
    o.categories.some((c) => c.toLowerCase() === String(cat).toLowerCase())
  );
}
